scrollToBottom() {
  const el = this.$refs.messageList
  if (el) el.scrollTop = el.scrollHeight
},
/** 把刚发出的问题行对齐到列表顶部，保证问题完整可见；已完整可见则不动滚动。 */
ensureQuestionVisible(id) {
  this.$nextTick(() => {
    const list = this.$refs.messageList
    const row = list && id ? list.querySelector(`[data-msg-id="${id}"]`) : null
    if (!list || !row) return
    const listRect = list.getBoundingClientRect()
    const rowRect = row.getBoundingClientRect()
    if (rowRect.top >= listRect.top - 1 && rowRect.bottom <= listRect.bottom + 1) return
    list.scrollTop += rowRect.top - listRect.top
  })
}

